250 :     } else {
251 :       // verify the function hasn't already been marked as "don't inline"
252 :       if (fs.canInline()) {
253 :         // store it for use when inlining.
254 :         fs.setFn(fn);
255 :         if (injector.isDirectCallNodeReplacementPossible(
256 :             fn.getFunctionNode())) {
257 :           fs.inlineDirectly(true);
258 :         }
259 : 
260 :         // verify the function meets all the requirements.
261 :         // TODO(johnlenz): Minimum requirement checks are about 5% of the
262 :         // run-time cost of this pass.
263 :         if (!isCandidateFunction(fn)) {
264 :           // It doesn't meet the requirements.
265 :           fs.setInline(false);
266 :         }
267 : 
268 :         // Set the module and gather names that need temporaries.
269 :         if (fs.canInline()) {
270 :           fs.setModule(module);
271 : 
272 :           Node fnNode = fn.getFunctionNode();
273 :           Set<String> namesToAlias =
274 :               FunctionArgumentInjector.findModifiedParameters(fnNode);
275 :           if (!namesToAlias.isEmpty()) {
276 :             fs.inlineDirectly(false);
277 :             fs.setNamesToAlias(namesToAlias);
278 :           }
279 : 
280 :           Node block = NodeUtil.getFunctionBody(fnNode);
281 :           if (NodeUtil.referencesThis(block)) {
282 :             fs.setReferencesThis(true);
283 :           }
284 : 
285 :           if (NodeUtil.containsFunction(block)) {
286 :             fs.setHasInnerFunctions(true);
287 :             // If there are inner functions, we can inline into global scope
288 :             // if there are no local vars or named functions.
289 :             // TODO(johnlenz): this can be improved by looking at the possible
290 :             // values for locals.  If there are simple values, or constants
291 :             // we could still inline.
292 :             if (!assumeMinimumCapture && hasLocalNames(fnNode)) {
293 :               fs.setInline(false);
294 :             }
295 :           }
296 :         }
297 : 
298 :         // Check if block inlining is allowed.
299 :         if (fs.canInline() && !fs.canInlineDirectly()) {
300 :           if (!blockFunctionInliningEnabled) {
301 :             fs.setInline(false);
302 :           }
303 :         }
304 :       }
305 :     }
306 :   }"

"119 :   boolean doesFunctionMeetMinimumRequirements(
120 :       final String fnName, Node fnNode) {
121 :     Node block = NodeUtil.getFunctionBody(fnNode);
122 : 
123 :     // Basic restrictions on functions that can be inlined:
124 :     // 0) The function is inlinable by convention
125 :     // 1) It contains a reference to itself.
126 :     // 2) It uses its parameters indirectly using "arguments" (it isn't
127 :     //    handled yet.
128 :     // 3) It references "eval". Inline a function containing eval can have
129 :     //    large performance implications.
130 : 
131 :     if (!compiler.getCodingConvention().isInlinableFunction(fnNode)) {
132 :       return false;
133 :     }
134 : 
135 :     final String fnRecursionName = fnNode.getFirstChild().getString();
136 :     Preconditions.checkState(fnRecursionName != null);
137 : 
138 :     // If the function references "arguments" directly in the function
139 :     boolean referencesArguments = NodeUtil.isNameReferenced(
140 :         block, "arguments", NodeUtil.MATCH_NOT_FUNCTION);
141 : 
142 :     // or it references "eval" or one of its names anywhere.
143 :     Predicate<Node> p = new Predicate<Node>(){
144 :       @Override
145 :       public boolean apply(Node n) {
146 :         if (n.isName()) {
147 :           return n.getString().equals("eval")
148 :             || (!fnName.isEmpty()
149 :                 && n.getString().equals(fnName))
150 :             || (!fnRecursionName.isEmpty()
151 :                 && n.getString().equals(fnRecursionName));
152 :         }
153 :         return false;
154 :       }
155 :     };
156 : 
157 :     return !referencesArguments
158 :         && !NodeUtil.has(block, p, Predicates.<Node>alwaysTrue());
159 :   }"

"333 :   private boolean isCandidateFunction(Function fn) {
334 :     // Don't inline exported functions.
335 :     String fnName = fn.getName();
336 :     if (compiler.getCodingConvention().isExported(fnName)) {
337 :       // TODO(johnlenz): Should we allow internal references to be inlined?
338 :       // An exported name can be replaced externally, any inlined instance
339 :       // would not reflect this change.
340 :       // To allow inlining we need to be able to distinguish between exports
341 :       // that are used in a read-only fashion and those that can be replaced
342 :       // by external definitions.
343 :       return false;
344 :     }
345 : 
346 :     // Don't inline this special function
347 :     if (RenameProperties.RENAME_PROPERTY_FUNCTION_NAME.equals(fnName)) {
348 :       return false;
349 :     }
350 : 
351 :     // Don't inline if we are specializing and the function can't be fixed up
352 :     if (specializationState != null &&
353 :         !specializationState.canFixupFunction(fn.getFunctionNode())) {
354 :       return false;
355 :     }
356 : 
357 :     Node fnNode = fn.getFunctionNode();
358 :     return injector.doesFunctionMeetMinimumRequirements(fnName, fnNode);
359 :   }"

